import type { Metadata } from "next";
import TopBar from "@/components/TopBar";
import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import ScrollToTop from "@/components/ScrollToTop";
import RevealOnScroll from "@/components/RevealOnScroll";
import { site } from "@/data";
// Fonts from site.json (theme.fonts), generated by scripts/fonts.mjs.
import { fontVariables } from "./fonts.generated";
import "./globals.css";

export const metadata: Metadata = {
  title: {
    default: site.navbar.seo.title,
    template: `%s | ${site.navbar.brand.name}`,
  },
  description: site.navbar.seo.description,
};

// Colours come from site.json (theme.colors) and override the globals.css defaults; invalid values are skipped.
const isHex = (v: string) => /^#([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(v);
const themeCss = `:root{${Object.entries(site.theme.colors)
  .filter(([, v]) => isHex(v))
  .map(([k, v]) => `--color-${k}:${v}`)
  .join(";")}}`;

// Hides [data-reveal] elements before first paint; removed again if the app script never starts.
const motionScript = `(function(d){d.classList.add("motion");setTimeout(function(){if(!window.__revealReady)d.classList.remove("motion")},3500)})(document.documentElement)`;

// Zooms the 1440px layout down on 1024-1440px screens (--site-zoom).
const zoomScript = `(function(d){function f(){var w=window.innerWidth;d.style.setProperty("--site-zoom",w>=1024&&w<1440?String(w/1440):"1")}f();window.addEventListener("resize",f)})(document.documentElement)`;

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    // suppressHydrationWarning: the inline scripts add the `motion` class and the zoom variable before React hydrates.
    <html lang="en" data-scroll-behavior="smooth" className={`${fontVariables} antialiased`} suppressHydrationWarning>
      <head>
        <style dangerouslySetInnerHTML={{ __html: themeCss }} />
        <script dangerouslySetInnerHTML={{ __html: motionScript }} />
        <script dangerouslySetInnerHTML={{ __html: zoomScript }} />
      </head>
      <body className="flex min-h-screen flex-col">
        <ScrollToTop />
        <RevealOnScroll />
        <TopBar data={site.navbar.topBar} contact={site.footer.contact} socials={site.footer.socials} />
        <Navbar data={site.navbar} contact={site.footer.contact} socials={site.footer.socials} />
        <main className="flex-1">{children}</main>
        <Footer data={site.footer} />
      </body>
    </html>
  );
}
